import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.when;

public class JacksonAnnotationIntrospector_findInjectableValueId_TriageGen2Test {

    private JacksonAnnotationIntrospector introspector;

    @Before
    public void setUp() {
        introspector = new JacksonAnnotationIntrospector();
    }

    /**
     * Test case: Annotation is not present.
     * Expected: returns null.
     */
    @Test
    public void testFindInjectableValueId_NoAnnotation() {
        AnnotatedMember m = Mockito.mock(AnnotatedMember.class);
        // We need to mock the internal _findAnnotation behavior. 
        // Since _findAnnotation is protected, we rely on the fact that 
        // the introspector will return null if no annotation is found.
        // In a real scenario, this is handled by the introspection logic.
        // For unit testing this specific method, we assume _findAnnotation returns null.

        // Note: In a real Jackson environment, _findAnnotation is called via reflection/internal logic.
        // Since we cannot easily mock the protected _findAnnotation without a spy, 
        // and the method logic depends on it, we assume a spy or a subclass for testing.

        JacksonAnnotationIntrospector spyIntrospector = Mockito.spy(new JacksonAnnotationIntrospector());
        when(spyIntrospector._findAnnotation(m, JacksonInject.class)).thenReturn(null);

        Object result = spyIntrospector.findInjectableValueId(m);
        assertNull(result);
    }

    /**
     * Test case: Annotation is present with a specific non-empty ID.
     * Expected: returns the ID string.
     */
    @Test
    public void testFindInjectableValueId_WithSpecificId() {
        AnnotatedMember m = Mockito.mock(AnnotatedMember.class);
        JacksonInject ann = Mockito.mock(JacksonInject.class);
        when(ann.value()).thenReturn("myCustomId");

        JacksonAnnotationIntrospector spyIntrospector = Mockito.spy(new JacksonAnnotationIntrospector());
        when(spyIntrospector._findAnnotation(m, JacksonInject.class)).thenReturn(ann);

        Object result = spyIntrospector.findInjectableValueId(m);
        assertEquals("myCustomId", result);
    }

    /**
     * Test case: Annotation is present with empty string, and member is NOT an AnnotatedMethod (e.g., a Field).
     * Expected: returns the raw type name.
     */
    @Test
    public void testFindInjectableValueId_EmptyId_Field() {
        AnnotatedMember m = Mockito.mock(AnnotatedMember.class);
        JacksonInject ann = Mockito.mock(JacksonInject.class);
        when(ann.value()).thenReturn("");
        when(m.getRawType()).thenReturn(String.class);

        JacksonAnnotationIntrospector spyIntrospector = Mockito.spy(new JacksonAnnotationIntrospector());
        when(spyIntrospector._findAnnotation(m, JacksonInject.class)).thenReturn(ann);

        Object result = spyIntrospector.findInjectableValueId(m);
        assertEquals(String.class.getName(), result);
    }

    /**
     * Test case: Annotation is present with empty string, and member IS an AnnotatedMethod with 0 parameters.
     * Expected: returns the raw type name.
     */
    @Test
    public void testFindInjectableValueId_EmptyId_MethodNoParams() {
        AnnotatedMethod am = Mockito.mock(AnnotatedMethod.class);
        JacksonInject ann = Mockito.mock(JacksonInject.class);
        when(ann.value()).thenReturn("");
        when(am.getParameterCount()).thenReturn(0);
        when(am.getRawType()).thenReturn(Integer.class);

        JacksonAnnotationIntrospector spyIntrospector = Mockito.spy(new JacksonAnnotationIntrospector());
        when(spyIntrospector._findAnnotation(am, JacksonInject.class)).thenReturn(ann);

        Object result = spyIntrospector.findInjectableValueId(am);
        assertEquals(Integer.class.getName(), result);
    }

    /**
     * Test case: Annotation is present with empty string, and member IS an AnnotatedMethod with parameters.
     * Expected: returns the name of the first parameter's type.
     */
    @Test
    public void testFindInjectableValueId_EmptyId_MethodWithParams() {
        AnnotatedMethod am = Mockito.mock(AnnotatedMethod.class);
        JacksonInject ann = Mockito.mock(JacksonInject.class);
        when(ann.value()).thenReturn("");
        when(am.getParameterCount()).thenReturn(1);
        // Mocking getRawParameterType(0)
        // Note: AnnotatedMethod is an interface/class in Jackson that returns a Class or JavaType.
        // For this test, we assume it returns a Class or something that has .getName()
        // Since the code calls .getName() on the result of getRawParameterType(0), 
        // we must mock it to return a class.
        when(am.getRawParameterType(0)).thenReturn(Double.class);

        JacksonAnnotationIntrospector spyIntrospector = Mockito.spy(new JacksonAnnotationIntrospector());
        when(spyIntrospector._findAnnotation(am, JacksonInject.class)).thenReturn(ann);

        Object result = spyIntrospector.findInjectableValueId(am);
        assertEquals(Double.class.getName(), result);
    }
}
